import{_ as e,o as r,c as d,a2 as a}from"./chunks/framework.hwbV7reR.js";const _=JSON.parse('{"title":"Разработка протокольного драйвера","description":"","frontmatter":{},"headers":[],"relativePath":"drivers.md","filePath":"drivers.md","lastUpdated":1791695486000}'),o={name:"drivers.md"};function i(n,t,l,s,c,p){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="разработка-протокольного-драивера" tabindex="-1">Разработка протокольного драйвера <a class="header-anchor" href="#разработка-протокольного-драивера" aria-label="Permalink to &quot;Разработка протокольного драйвера&quot;">​</a></h1><p>Сегодня реализован AmneziaWG. <a href="./trusttunnel.html">Испытания TrustTunnel</a> и адаптер его документа и экспериментальный API-адаптер доступны отдельно от рабочего реестра драйверов. Наличие TrustTunnel в моделях — подготовка контракта, а не готовая поддержка. Внешней plugin-системы и загрузки произвольного Python-кода из настроек нет: новый драйвер добавляется проверяемым изменением репозитория.</p><h2 id="граница-ответственности" tabindex="-1">Граница ответственности <a class="header-anchor" href="#граница-ответственности" aria-label="Permalink to &quot;Граница ответственности&quot;">​</a></h2><p><a href="https://github.com/UndercoreCo/orchestrator/blob/main/orchestrator/application/ports.py" target="_blank" rel="noreferrer">NodeDriver</a> описывает операции драйвера. Оркестратор выбирает узел, сохраняет назначение, контролирует ревизии и переключения. Драйвер знает протокол узла, проверяет ответы, выдаёт транспортные параметры и выбирает форматы экспорта. Backend решает вопросы пользователя и права на доступ.</p><table tabindex="0"><thead><tr><th>Метод</th><th>Обязанность</th></tr></thead><tbody><tr><td>verify</td><td>Проверить идентичность узла до включения в реестр</td></tr><tr><td>observe/list</td><td>Проверить идентичность узла, получить наблюдение и клиентов</td></tr><tr><td>create</td><td>Повторяемо создать доступ по стабильному binding_key</td></tr><tr><td>get/validate</td><td>Проверить состояние и соответствие remote_id/external_id</td></tr><tr><td>mutate</td><td>Продлить, включить, отозвать или заменить доступ с сохранением повторяемости</td></tr><tr><td>connection</td><td>Вернуть согласованные состояние и транспортные параметры</td></tr><tr><td>configuration</td><td>Вернуть типизированный документ движка</td></tr><tr><td>export</td><td>Выбрать и валидировать представление, вернуть ExportDocument</td></tr></tbody></table><p>Повтор create после потери ответа должен найти тот же peer. Срок должен исполняться на узле. Отзыв требует подтверждения: таймаут API не означает успешного удаления. Без этих трёх гарантий DriverRegistry не принимает драйвер.</p><h2 id="порядок-реализации" tabindex="-1">Порядок реализации <a class="header-anchor" href="#порядок-реализации" aria-label="Permalink to &quot;Порядок реализации&quot;">​</a></h2><ol><li>Опишите реальные возможности API целевого узла и его гарантии при сбоях.</li><li>Реализуйте адаптер транспорта отдельно от протокольных проверок. Смотрите <code>amnezia_http.py</code> и <code>amneziawg.py</code> как текущий пример, а не обязательный wire-формат.</li><li>Реализуйте NodeDriver и DriverCapabilities, включая поддерживаемые экспорты.</li><li>Зарегистрируйте драйвер в <code>bootstrap.py</code>; обновите разрешённые протоколы в моделях, реестре и проверке настроек, если добавляется новое имя протокола.</li><li>Добавьте соответствие protocol/format в TransportConfiguration и схемы.</li><li>Если узел поддерживает lease, реализуйте <code>LeaseTransport</code> (probe/observe/renew) и зарегистрируйте его в <code>LeaseRegistry</code> через bootstrap. Нельзя включать lease_enabled без независимого прекращения доступа на узле и тестов fencing. Прикладной сценарий использует только LeaseObservation и LeaseGrant.</li><li>Пересоберите контракты, обновите документацию и включайте capability только после полного прохождения жизненного цикла.</li></ol><p>Одна реализация export не делает WireGuard или TrustTunnel рабочим драйвером. Динамическое определение доступных экспортов уже есть; общий PNG renderer не должен выбирать узел или понимать аккаунты.</p><h2 id="обязательная-матрица-проверок" tabindex="-1">Обязательная матрица проверок <a class="header-anchor" href="#обязательная-матрица-проверок" aria-label="Permalink to &quot;Обязательная матрица проверок&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Сценарий</th><th>Ожидаемый результат</th></tr></thead><tbody><tr><td>Повтор создания</td><td>Тот же remote_id, без второго peer</td></tr><tr><td>Потерян ответ мутации</td><td>Повтор использует прежнюю идентичность/ключ</td></tr><tr><td>Неверный server_id или binding</td><td>Отказ выдачи конфигурации</td></tr><tr><td>Истёкший/отключённый доступ</td><td>Нет экспорта; срок исполняется узлом</td></tr><tr><td>Неподтверждённый отзыв</td><td>Переключение не объявляется завершённым</td></tr><tr><td>Перезапуск controller</td><td>Незавершённая операция продолжает прежнюю цель</td></tr><tr><td>Несовместимый клиент/формат</td><td>Явная ошибка без скрытой замены протокола</td></tr><tr><td>Ошибка upstream</td><td>Нет секретов в ответе, repr, CLI и журналах</td></tr></tbody></table><p><code>tests/test_driver_contract.py</code> — общий параметризованный набор: повтор создания, потеря ответа, подтверждённый отзыв, запрет экспорта после истечения срока, проверка binding и доступные форматы. Сейчас он запускается с реальным адаптером Amnezia против двух вариантов HTTP-контракта закреплённого агента; kernel заменён тестовой реализацией. Для нового протокола добавьте fixture с его реальным адаптером, API и способом управлять временем/сбоями, сохранив общие проверки.</p><p>Сценарии переключения, fencing и восстановления проверяются дополнительно в <code>test_node_switch</code>, <code>test_leases</code>, <code>test_connection_contract</code> и <code>test_exports</code>. Общий набор не заменяет эту матрицу и проверку на реальном узле. Тестовый transport TrustTunnel в проверке границ доказывает только внедрение зависимости; рабочей реализации TrustTunnel пока нет.</p>',13)])])}const b=e(o,[["render",i]]);export{_ as __pageData,b as default};
